package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import java.math.*; import java.util.*;
@Entity @Table(name="rsp_evaluation_policy_stage",uniqueConstraints=@UniqueConstraint(name="uk_rsp_evaluation_stage_code",columnNames={"agency_id","policy_id","normalized_code"}))
public class EvaluationStage extends RspAuditedEntity {
 public enum Type { WRITTEN_EXAMINATION,TECHNICAL_SKILLS_TEST,COMPETENCY_BASED_INTERVIEW,BEHAVIORAL_EVENT_INTERVIEW,BACKGROUND_REFERENCE_CHECK,OTHER_CONFIGURED } public enum Mode { SCORED,GATE,INFORMATIONAL }
 @Column(name="policy_id",nullable=false,length=36) private String policyId; @Column(nullable=false,length=80) private String code; @Column(name="normalized_code",nullable=false,length=80) private String normalizedCode; @Column(nullable=false,length=200) private String name; @Column(length=2000) private String instructions; @Enumerated(EnumType.STRING) @Column(name="stage_type",nullable=false,length=40) private Type type; @Enumerated(EnumType.STRING) @Column(name="stage_mode",nullable=false,length=20) private Mode mode; @Column(nullable=false,precision=7,scale=4) private BigDecimal weight; @Column(name="maximum_score",precision=12,scale=4) private BigDecimal maximumScore; @Column(name="passing_score",precision=12,scale=4) private BigDecimal passingScore; @Column(name="minimum_raters",nullable=false) private int minimumRaters; @Column(name="requires_evidence",nullable=false) private boolean requiresEvidence; @Column(name="display_order",nullable=false) private int displayOrder;
 protected EvaluationStage(){}
 public EvaluationStage(String agency,String policy,String code,String name,String instructions,Type type,Mode mode,BigDecimal weight,BigDecimal max,BigDecimal pass,int raters,boolean evidence,int order){super(agency);policyId=requiredText(policy,"policyId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.name=requiredText(name,"name");this.instructions=optionalText(instructions);this.type=Objects.requireNonNull(type);this.mode=Objects.requireNonNull(mode);this.weight=Objects.requireNonNull(weight);maximumScore=max;passingScore=pass;minimumRaters=raters;requiresEvidence=evidence;displayOrder=order;validate();}
 private void validate(){if(displayOrder<0||minimumRaters<1)throw new IllegalArgumentException("displayOrder and minimumRaters are invalid");if(weight.signum()<0||weight.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("Stage weight must be between 0 and 100");if(mode==Mode.SCORED&&(weight.signum()==0||maximumScore==null||maximumScore.signum()<=0))throw new IllegalArgumentException("A scored stage requires positive weight and maximumScore");if(mode!=Mode.SCORED&&weight.signum()!=0)throw new IllegalArgumentException("Gate and informational stages must have zero weight");if(maximumScore!=null&&maximumScore.signum()<=0)throw new IllegalArgumentException("maximumScore must be positive");if(passingScore!=null&&(passingScore.signum()<0||maximumScore!=null&&passingScore.compareTo(maximumScore)>0))throw new IllegalArgumentException("passingScore is outside the score bounds");}
 public String getPolicyId(){return policyId;} public String getCode(){return code;} public String getName(){return name;} public String getInstructions(){return instructions;} public Type getType(){return type;} public Mode getMode(){return mode;} public BigDecimal getWeight(){return weight;} public BigDecimal getMaximumScore(){return maximumScore;} public BigDecimal getPassingScore(){return passingScore;} public int getMinimumRaters(){return minimumRaters;} public boolean isRequiresEvidence(){return requiresEvidence;} public int getDisplayOrder(){return displayOrder;}
}
